function CatalogueReview(){
  const [rows,setRows]=useState([]),[notice,setNotice]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[showAll,setShowAll]=useState(false);
  const load=()=>api.get('/admin/catalogue-review').then(r=>setRows(r.data));
  useEffect(()=>{load().catch(()=>{});},[]);

  const chipsFor=(row)=>Object.entries(row.source_data||{})
    .filter(([column,value])=>column!=='A' && value && String(value).trim())
    .slice(0,5)
    .map(([column,value])=>({column,value:String(value).trim()}));

  const reasonLabel=(reason)=>{
    if(!reason) return 'Needs a decision';
    if(String(reason).startsWith('Category, family')) return 'Category / brand matrix row — not a product';
    return String(reason).replace(/\.$/,'');
  };

  const linkedCount=rows.filter(row=>row.imported_product_id).length;
  const term=query.trim().toLowerCase();
  const visible=rows.filter(row=>{
    const linked=Boolean(row.imported_product_id);
    const matchesFilter=filter==='all'||(filter==='linked'?linked:!linked);
    const haystack=[row.row_number,row.product_name,row.review_reason,JSON.stringify(row.source_data||{})].join(' ').toLowerCase();
    return matchesFilter&&(!term||haystack.includes(term));
  });

  const shown=showAll?visible:visible.slice(0,12);
  const mark=async row=>{
    try{
      await api.patch(`/admin/catalogue-review/${row.id}`,{resolve:Boolean(row.imported_product_id)});
      setNotice(`Row ${row.row_number} marked reviewed.`);
      load();
    }catch(err){
      setNotice(err.response?.data?.error||'Could not update this row.');
    }
  };

  return <div className="review-page">
    <PageHeading eyebrow="SOURCE CATALOGUE" title="Catalogue review"><span className="count-pill">{rows.length} flagged rows</span></PageHeading>
    <section className="review-intro">
      <div className="review-intro-copy"><span>WHAT THIS MEANS</span><h2>Decide what each imported row represents.</h2><p>These rows were preserved from the workbook. Most are category and brand matrix headings, not products. Open a row only when you need to inspect the original spreadsheet cells.</p></div>
      <div className="review-summary">
        <div><b>{rows.length}</b><small>Flagged rows</small></div>
        <div><b>{linkedCount}</b><small>Linked to products</small></div>
        <div><b>{rows.length-linkedCount}</b><small>Needs a decision</small></div>
      </div>
    </section>
    {notice&&<p className="form-success">{notice}</p>}
    <section className="admin-panel review-panel">
      <div className="admin-panel-head review-toolbar">
        <div><h2>Rows that need attention</h2><p>Search by row, product or reason. Raw cells stay collapsed until you open them.</p></div>
        <div className="review-controls">
          <input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search rows…" aria-label="Search review rows"/>
          <div className="review-filters">
            <button type="button" className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>All</button>
            <button type="button" className={filter==='pending'?'active':''} onClick={()=>setFilter('pending')}>Needs decision</button>
            <button type="button" className={filter==='linked'?'active':''} onClick={()=>setFilter('linked')}>Linked</button>
          </div>
        </div>
      </div>
      {shown.length?<div className="review-list">{shown.map(row=>{
        const chips=chipsFor(row);
        const linked=Boolean(row.imported_product_id);
        return <article className="review-card" key={row.id}>
          <div className="review-card-top"><span className="review-row">ROW {row.row_number} · {row.sheet_name}</span><span className={`review-status ${linked?'linked':'pending'}`}>{linked?'Linked to product':'Needs decision'}</span></div>
          <div className="review-card-main"><div><h3>{row.product_name||chips[0]?.value||`Spreadsheet row ${row.row_number}`}</h3><p>{reasonLabel(row.review_reason)}</p></div>{linked&&<Link className="small-action" to="/admin/products">Open product</Link>}</div>
          {chips.length>0&&<div className="review-chips">{chips.map(chip=><span key={chip.column}><b>{chip.column}</b>{chip.value}</span>)}</div>}
          <div className="review-card-actions"><details className="review-source"><summary>Inspect source row</summary><pre>{JSON.stringify(row.source_data,null,2)}</pre></details><button type="button" className="button button-outline-dark" onClick={()=>mark(row)} title="Remove this row from the review list">Mark reviewed</button></div>
        </article>;
      })}{visible.length>12&&<button type="button" className="review-show-more" onClick={()=>setShowAll(!showAll)}>{showAll?'Show fewer rows':`Show all ${visible.length} rows`}</button>}</div>:<div className="review-empty"><ShieldCheck size={25}/><h3>{rows.length?'No matching rows':'No rows need review'}</h3><p>{rows.length?'Try a different search or filter.':'Import flags will appear here after the product workbook is loaded.'}</p></div>}
    </section>
  </div>;
}

function EnquiryTable({rows,compact=false}){return <div className="admin-table-wrap"><table><thead><tr><th>Reference / Customer</th><th>Requirement</th><th>Contact</th><th>Status</th><th>Received</th></tr></thead><tbody>{rows.map(e=><tr key={e.id||e.reference_no}><td><b>{e.reference_no}</b><small>{e.customer_name}{e.company_name?` · ${e.company_name}`:''}</small></td><td>{e.product_name||e.category_name||'General enquiry'}</td><td><a href={`tel:${e.mobile}`}>{e.mobile}</a></td><td><span className="status-active">{e.status}</span></td><td>{e.created_at?new Date(e.created_at).toLocaleDateString():'—'}</td></tr>)}{!rows.length&&<tr><td colSpan="5" className="table-empty">No enquiries to show.</td></tr>}</tbody></table></div>}
function EnquiryManager(){const [rows,setRows]=useState([]),[team,setTeam]=useState([]),[status,setStatus]=useState(''),[noteId,setNoteId]=useState(null),[note,setNote]=useState(''),[error,setError]=useState('');const load=()=>Promise.all([api.get('/admin/enquiries',{params:status?{status}:{}}),api.get('/admin/team')]).then(([r,t])=>{setRows(r.data);setTeam(t.data);});useEffect(()=>{load().catch(()=>{});},[status]);const save=async(id,fields)=>{try{await api.patch(`/admin/enquiries/${id}`,fields);await load();}catch(e){setError(e.response?.data?.error||'Could not update enquiry.');}};const csv=async()=>{const r=await api.get('/admin/enquiries.csv',{responseType:'blob'});const url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download='lakshmi-enquiries.csv';a.click();URL.revokeObjectURL(url);};return <><PageHeading eyebrow="CUSTOMER RELATIONSHIPS" title="Enquiry management"><button className="button button-outline-dark" onClick={csv}>Export CSV</button></PageHeading>{error&&<div className="form-error">{error}</div>}<section className="admin-panel"><div className="admin-panel-head"><div><h2>Customer enquiries</h2><p>Track responses, ownership and internal follow-up notes.</p></div><select className="filter-select" value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option>{['New','Contacted','Quotation Sent','Follow-up','Converted','Closed'].map(s=><option key={s}>{s}</option>)}</select></div><div className="admin-table-wrap"><table><thead><tr><th>Reference / Customer</th><th>Requirement</th><th>Contact</th><th>Status</th><th>Assigned to</th><th>Received</th><th></th></tr></thead><tbody>{rows.map(e=><><tr key={e.id}><td><b>{e.reference_no}</b><small>{e.customer_name}{e.company_name?` · ${e.company_name}`:''}</small></td><td>{e.product_name||e.category_name||'General enquiry'}<small>{e.quantity?`Qty: ${e.quantity}`:''}</small>{e.attachments?.map(a=><small key={a.id}><a href={a.file_url} target="_blank" rel="noreferrer">Attachment: {a.original_name}</a></small>)}</td><td><a href={`tel:${e.mobile}`}>{e.mobile}</a>{e.email&&<small>{e.email}</small>}</td><td><select className="status-select" value={e.status} onChange={ev=>save(e.id,{status:ev.target.value})}>{['New','Contacted','Quotation Sent','Follow-up','Converted','Closed'].map(s=><option key={s}>{s}</option>)}</select></td><td><select className="status-select" value={e.assigned_admin_id||''} onChange={ev=>save(e.id,{assigned_admin_id:ev.target.value?Number(ev.target.value):null})}><option value="">Unassigned</option>{team.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></td><td>{new Date(e.created_at).toLocaleDateString()}</td><td><button className="small-action" onClick={()=>setNoteId(noteId===e.id?null:e.id)}>{noteId===e.id?'Close':'Notes'}</button></td></tr>{noteId===e.id&&<tr key={`${e.id}-notes`}><td colSpan="7"><div className="note-thread">{e.notes?.length?e.notes.map(n=><p key={n.id}><b>{n.admin_name} · {new Date(n.created_at).toLocaleString()}</b>{n.note}</p>):<small>No internal notes yet.</small>}</div><div className="note-editor"><label>Internal note<textarea rows="2" value={note} onChange={ev=>setNote(ev.target.value)} placeholder="Add a follow-up reminder or customer update"/></label><button className="button button-dark" onClick={()=>{if(note.trim()){save(e.id,{note});setNote('');}}}>Save note</button></div></td></tr>}</>)}{!rows.length&&<tr><td colSpan="7" className="table-empty">No enquiries to show.</td></tr>}</tbody></table></div></section></>}

function SettingsManager(){const [values,setValues]=useState({}),[notice,setNotice]=useState('');useEffect(()=>{api.get('/admin/settings').then(r=>setValues(Object.fromEntries(Object.entries(r.data).map(([k,v])=>[k,v.value||''])))).catch(()=>{});},[]);const set=(k,v)=>setValues(s=>({...s,[k]:v}));const save=async e=>{e.preventDefault();try{await api.put('/admin/settings',values);setNotice('Settings saved.');}catch(err){setNotice(err.response?.data?.error||'Unable to save settings.');}};const fields=[['business_name','Business name'],['address','Business address'],['phones','Contact numbers (comma separated)'],['email','Business email'],['gst_number','GST number'],['whatsapp_number','WhatsApp number (international format)'],['google_maps_query','Google Maps search location'],['facebook_url','Facebook URL'],['instagram_url','Instagram URL'],['linkedin_url','LinkedIn URL'],['footer_text','Footer information'],['bank_name','Bank name (admin only)'],['bank_account','Bank account (admin only)'],['bank_ifsc','Bank IFSC (admin only)'],['bank_branch','Bank branch (admin only)']];return <><PageHeading eyebrow="WEBSITE CONFIGURATION" title="Business settings"/><section className="admin-panel"><div className="admin-panel-head"><div><h2>Business information</h2><p>Private bank fields are available only inside the authenticated admin area.</p></div></div>{notice&&<p className="form-success">{notice}</p>}<form className="admin-form settings-form" onSubmit={save}><div className="admin-form-grid">{fields.map(([k,l])=><label key={k}>{l}{['address','footer_text'].includes(k)?<textarea rows="3" value={values[k]||''} onChange={e=>set(k,e.target.value)}/>:<input type={k.includes('account')?'password':'text'} value={values[k]||''} onChange={e=>set(k,e.target.value)}/>}</label>)}</div><button className="button button-dark"><Save size={15}/> Save settings</button></form></section></>}

function BrandLogoManager(){const [url,setUrl]=useState(''),[notice,setNotice]=useState('');useEffect(()=>{api.get('/admin/settings').then(r=>setUrl(r.data.logo_url?.value||'')).catch(()=>{});},[]);const upload=async e=>{const file=e.target.files?.[0];if(!file)return;try{const imageUrl=await uploadImage(file);setUrl(imageUrl);setNotice('Image uploaded. Save to publish it in the header and footer.');}catch(err){setNotice(err.response?.data?.error||'Logo upload failed.');}};const save=async()=>{try{await api.put('/admin/settings',{logo_url:url});setNotice('Logo setting saved.');}catch(err){setNotice(err.response?.data?.error||'Unable to save the logo setting.');}};return <section className="admin-panel"><div className="admin-panel-head"><div><h2>Website logo</h2><p>Used in the public header and footer.</p></div></div>{notice&&<p className="form-success">{notice}</p>}<div className="admin-form admin-logo-setting"><label>Upload logo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={upload}/><small>JPG, PNG or WebP · max 8 MB. A transparent PNG is recommended.</small></label><img src={assetURL(url)||SITE_LOGO} alt="Current website logo preview"/><button className="button button-dark" onClick={save}>Save logo</button></div></section>}

function PasswordChanger(){const [form,setForm]=useState({currentPassword:'',newPassword:'',confirm:''}),[notice,setNotice]=useState('');const save=async e=>{e.preventDefault();setNotice('');if(form.newPassword!==form.confirm){setNotice('The new passwords do not match.');return;}try{await api.post('/admin/auth/change-password',{currentPassword:form.currentPassword,newPassword:form.newPassword});setNotice('Password updated.');setForm({currentPassword:'',newPassword:'',confirm:''});}catch(err){setNotice(err.response?.data?.error||'Unable to change password.');}};return <section className="admin-panel"><div className="admin-panel-head"><div><h2>Change admin password</h2><p>Use a unique password with at least 12 characters.</p></div></div>{notice&&<p className={notice==='Password updated.'?'form-success':'form-error'}>{notice}</p>}<form className="admin-form admin-form-grid" onSubmit={save}><label>Current password<input required type="password" autoComplete="current-password" value={form.currentPassword} onChange={e=>setForm({...form,currentPassword:e.target.value})}/></label><label>New password<input required minLength="12" type="password" autoComplete="new-password" value={form.newPassword} onChange={e=>setForm({...form,newPassword:e.target.value})}/></label><label>Confirm new password<input required minLength="12" type="password" autoComplete="new-password" value={form.confirm} onChange={e=>setForm({...form,confirm:e.target.value})}/></label><button className="button button-dark"><Save size={15}/> Update password</button></form></section>}

function ContentManager(){const [pages,setPages]=useState([]),[key,setKey]=useState('home'),[form,setForm]=useState(null),[notice,setNotice]=useState('');useEffect(()=>{api.get('/admin/content').then(r=>{setPages(r.data);const p=r.data.find(x=>x.page_key==='home');setForm(p||{title:'',body:'',meta_title:'',meta_description:''});}).catch(()=>{});},[]);const select=k=>{setKey(k);const p=pages.find(x=>x.page_key===k);setForm(p?{...p}:{title:'',body:'',meta_title:'',meta_description:''});};const save=async e=>{e.preventDefault();try{await api.put(`/admin/content/${key}`,form);setNotice('Page content saved.');const r=await api.get('/admin/content');setPages(r.data);}catch(err){setNotice(err.response?.data?.error||'Unable to save page.');}};return <><PageHeading eyebrow="CONTENT MANAGEMENT" title="Page content"/><section className="admin-panel"><div className="admin-panel-head"><div><h2>Public page copy</h2><p>Edit homepage, about, service and contact page content.</p></div><select value={key} onChange={e=>select(e.target.value)}>{['home','about','services','contact'].map(k=><option key={k} value={k}>{k[0].toUpperCase()+k.slice(1)}</option>)}</select></div>{notice&&<p className="form-success">{notice}</p>}{form&&<form className="admin-form content-editor" onSubmit={save}><label>Page heading<input value={form.title||''} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Page copy<textarea rows="8" value={form.body||''} onChange={e=>setForm({...form,body:e.target.value})}/></label><div className="admin-form-row"><label>SEO title<input value={form.meta_title||''} onChange={e=>setForm({...form,meta_title:e.target.value})}/></label><label>SEO description<input value={form.meta_description||''} onChange={e=>setForm({...form,meta_description:e.target.value})}/></label></div><button className="button button-dark"><Save size={15}/> Save page</button></form>}</section></>}

export default function Admin(){return <Routes><Route index element={<Login/>}/><Route path="/*" element={<AdminShell/>}/></Routes>}

